WITH enriched AS (SELECT s.id, s.order_id, s.shipped_date, s.cost, s.status, d.status AS order_status, d.amount, d.shipping_fee FROM shipments s LEFT JOIN orders d ON s.order_id <=> d.id) SELECT order_id, CASE WHEN shipping_fee >= 35 THEN 'LARGE' ELSE 'SMALL' END AS shipping_fee_tier, DATE_TRUNC('MONTH', shipped_date) AS activity_month, COUNT(CASE WHEN status = 'IN_TRANSIT' THEN 1 END) AS in_transit_count, SIZE(COLLECT_SET(status)) AS num_status, STDDEV_SAMP(cost) AS cost_stddev, COUNT(DISTINCT order_id) AS distinct_order_ids, SIZE(COLLECT_SET(order_status)) AS num_order_status FROM enriched GROUP BY order_id, CASE WHEN shipping_fee >= 35 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('MONTH', shipped_date) ORDER BY order_id NULLS FIRST
